from pathlib import Path
import csv
import statistics

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190114", "20190115", "20190116", "20190119", "20190120", "20190121"]

# Collect all pipeline data
all_data = {}  # pipeline_name -> {date: flow_value}

for date in dates:
    csv_path = DIR / f"{date}_pipeline.csv"
    with open(csv_path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            pipeline_name = row.get('pipeline_name', '').strip()
            flow_str = row.get('flow', '').strip()
            if pipeline_name and flow_str:
                try:
                    flow_val = float(flow_str)
                except ValueError:
                    continue
                if pipeline_name not in all_data:
                    all_data[pipeline_name] = {}
                all_data[pipeline_name][date] = flow_val

# Filter for 西气东输一线 pipelines
xqds_pipelines = {k: v for k, v in all_data.items() if '西气东输一线' in k}

print(f"Found {len(xqds_pipelines)} 西气东输一线 pipelines")

# Calculate standard deviation for each pipeline
results = []
for pipeline_name, daily_flows in xqds_pipelines.items():
    values = list(daily_flows.values())
    if len(values) >= 2:
        std_dev = statistics.stdev(values)
        results.append((pipeline_name, std_dev, daily_flows))

# Sort by std_dev descending
results.sort(key=lambda x: x[1], reverse=True)

print("\nTop 2 pipelines by flow standard deviation:")
for i, (pipeline_name, std_dev, daily_flows) in enumerate(results[:2], 1):
    print(f"\n{i}. {pipeline_name}")
    print(f"   Standard deviation: {std_dev:.4f}")
    print(f"   Daily values:")
    for date in dates:
        if date in daily_flows:
            print(f"     {date}: {daily_flows[date]:.4f}")

