user_totals = defaultdict(float)
user_points = defaultdict(set)

with csv_path.open("r", encoding="utf-8-sig", newline="") as f:
    for row in csv.DictReader(f):
        if row["所属地"] == "贵州":
            user_totals[row["用户"]] += float(row["消耗量"])
            user_points[row["用户"]].add(row["供气点"])

ranked = sorted(user_totals.items(), key=lambda item: (-item[1], item[0]))
result = {
    "source_file": "20191219_consumer.csv",
    "region": "贵州",
    "ranking_scope": "按用户名称聚合后，消耗量降序；并列时按用户名称升序",
